base = json.load(open('lines.json'))
# drop previously generated ids in this module's space so the file can be regenerated
base = [b for b in base if not b['id'].startswith(('x','s'))]
out = list(base)
for i,(k,lines) in enumerate(L.items()):
    for j,l in enumerate(lines):
        out.append({"id":f"x{i:03d}{'ab'[j]}","nouns":k.split("|"),"line":l})
for i,(k,needs,l) in enumerate(SPECIFIC):
    out.append({"id":f"s{i:03d}","nouns":k.split("|"),"needs":needs,"line":l})
json.dump(out, open('lines.json','w'), indent=1, ensure_ascii=False)
print(len(out), "lines;", len({tuple(o['nouns']) for o in out}), "noun groups;", sum(1 for o in out if 'needs' in o), "specific")
